import { FormField, type FormFieldConfig } from "@/components/formfield";
import { kleinBottleGeometry } from "@/components/formfield/geometries/klein-bottle";

const KleinBottleFieldGeometries = [kleinBottleGeometry] as const;

export const KleinBottleFieldConfig = {
  "version": 1,
  "shape": "klein",
  "theme": {
    "background": "#000000",
    "star": "#FFFFFF",
    "glow": "#FFFFFF"
  },
  "motion": {
    "flowSpeed": 1,
    "pointScale": 1,
    "morphDuration": 1.35
  },
  "effects": {
    "hoverRadius": 220,
    "hoverIntensity": 1,
    "trailIntensity": 1
  },
  "interaction": {
    "enabled": false,
    "holdMode": "magnet"
  }
} satisfies FormFieldConfig;

export function KleinBottleField() {
  return (
    <div style={{ width: "100%", minHeight: 420, aspectRatio: "1 / 1" }}>
      <FormField config={KleinBottleFieldConfig} geometries={KleinBottleFieldGeometries} />
    </div>
  );
}
